CREATE TABLE "clients" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(200) NOT NULL,
    "company_name" VARCHAR(200) NOT NULL DEFAULT '',
    "email" VARCHAR(254) NOT NULL UNIQUE,
    "phone" VARCHAR(20) NOT NULL DEFAULT '',
    "alternate_phone" VARCHAR(20) NOT NULL DEFAULT '',
    "address" TEXT NOT NULL DEFAULT '',
    "city" VARCHAR(100) NOT NULL DEFAULT '',
    "state" VARCHAR(100) NOT NULL DEFAULT '',
    "country" VARCHAR(100) NOT NULL DEFAULT '',
    "website" VARCHAR(200) NOT NULL DEFAULT '',
    "industry" VARCHAR(50) NOT NULL DEFAULT '',
    "status" VARCHAR(20) NOT NULL DEFAULT 'lead',
    "notes" TEXT NOT NULL DEFAULT '',
    "currency" VARCHAR(10) NOT NULL DEFAULT 'USD',
    "currency_symbol" VARCHAR(5) NOT NULL DEFAULT '$',
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "assigned_manager_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "created_by_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "projects" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(200) NOT NULL,
    "description" TEXT NOT NULL DEFAULT '',
    "client_id" BIGINT NOT NULL REFERENCES "clients" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "project_manager_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "start_date" DATE NULL,
    "deadline" DATE NULL,
    "budget" NUMERIC(15, 2) NULL,
    "currency" VARCHAR(10) NOT NULL DEFAULT 'USD',
    "currency_symbol" VARCHAR(5) NOT NULL DEFAULT '$',
    "status" VARCHAR(20) NOT NULL DEFAULT 'planning',
    "priority" VARCHAR(20) NOT NULL DEFAULT 'medium',
    "progress" INTEGER NOT NULL DEFAULT 0,
    "notes" TEXT NOT NULL DEFAULT '',
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "projects_assigned_team" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "project_id" BIGINT NOT NULL REFERENCES "projects" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "user_id" BIGINT NOT NULL REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "projects_assigned_team_project_id_user_id_uniq" UNIQUE ("project_id", "user_id")
);

CREATE TABLE "tasks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "title" VARCHAR(300) NOT NULL,
    "description" TEXT NOT NULL DEFAULT '',
    "project_id" BIGINT NOT NULL REFERENCES "projects" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "client_id" BIGINT NULL REFERENCES "clients" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "assigned_to_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "priority" VARCHAR(20) NOT NULL DEFAULT 'medium',
    "status" VARCHAR(20) NOT NULL DEFAULT 'pending',
    "start_date" DATE NULL,
    "due_date" DATE NULL,
    "completion_date" DATE NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "task_comments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "task_id" BIGINT NOT NULL REFERENCES "tasks" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "user_id" BIGINT NOT NULL REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "comment" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "invoices" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "invoice_number" VARCHAR(50) NOT NULL UNIQUE,
    "client_id" BIGINT NOT NULL REFERENCES "clients" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "project_id" BIGINT NULL REFERENCES "projects" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "invoice_date" DATE NOT NULL,
    "due_date" DATE NOT NULL,
    "items" JSONB NOT NULL DEFAULT '[]'::jsonb,
    "subtotal" NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    "discount" NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    "discount_percent" NUMERIC(5, 2) NOT NULL DEFAULT 0.00,
    "tax" NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    "tax_percent" NUMERIC(5, 2) NOT NULL DEFAULT 0.00,
    "total" NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    "paid_amount" NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    "currency" VARCHAR(10) NOT NULL DEFAULT 'USD',
    "currency_symbol" VARCHAR(5) NOT NULL DEFAULT '$',
    "status" VARCHAR(20) NOT NULL DEFAULT 'draft',
    "notes" TEXT NOT NULL DEFAULT '',
    "terms" TEXT NOT NULL DEFAULT '',
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "payments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "client_id" BIGINT NOT NULL REFERENCES "clients" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "project_id" BIGINT NULL REFERENCES "projects" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "invoice_id" BIGINT NULL REFERENCES "invoices" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "amount" NUMERIC(15, 2) NOT NULL,
    "payment_method" VARCHAR(20) NOT NULL DEFAULT 'bank_transfer',
    "transaction_id" VARCHAR(200) NOT NULL DEFAULT '',
    "payment_date" DATE NOT NULL,
    "currency" VARCHAR(10) NOT NULL DEFAULT 'USD',
    "currency_symbol" VARCHAR(5) NOT NULL DEFAULT '$',
    "notes" TEXT NOT NULL DEFAULT '',
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "recorded_by_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "documents" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(300) NOT NULL,
    "document_type" VARCHAR(50) NOT NULL DEFAULT 'other',
    "client_id" BIGINT NULL REFERENCES "clients" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "project_id" BIGINT NULL REFERENCES "projects" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "file" VARCHAR(100) NOT NULL,
    "file_size" INTEGER NOT NULL DEFAULT 0,
    "file_type" VARCHAR(50) NOT NULL DEFAULT '',
    "description" TEXT NOT NULL DEFAULT '',
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "uploaded_by_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "notifications" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "recipient_id" BIGINT NOT NULL REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    "notification_type" VARCHAR(30) NOT NULL,
    "title" VARCHAR(200) NOT NULL,
    "message" TEXT NOT NULL,
    "is_read" BOOLEAN NOT NULL DEFAULT FALSE,
    "related_entity_type" VARCHAR(30) NOT NULL DEFAULT '',
    "related_entity_id" INTEGER NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "activities" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "action" VARCHAR(30) NOT NULL DEFAULT 'other',
    "entity_type" VARCHAR(30) NOT NULL DEFAULT '',
    "entity_id" INTEGER NULL,
    "entity_name" VARCHAR(300) NOT NULL DEFAULT '',
    "description" TEXT NOT NULL,
    "ip_address" VARCHAR(45) NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "token_blacklist_outstandingtoken" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "token" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ NULL,
    "expires_at" TIMESTAMPTZ NOT NULL,
    "user_id" BIGINT NULL REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    "jti" VARCHAR(255) NOT NULL UNIQUE
);

CREATE TABLE "token_blacklist_blacklistedtoken" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "blacklisted_at" TIMESTAMPTZ NOT NULL,
    "token_id" BIGINT NOT NULL UNIQUE REFERENCES "token_blacklist_outstandingtoken" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);

